  "2024-intern-anuj-rubrik": {
    "slug": "2024-intern-anuj-rubrik",
    "wordCount": 252,
    "readTime": "2 min read",
    "blocks": [
      {
        "type": "p",
        "content": "Anuj, studying in IIT Kanpur as a  student in Anuj, 210166 CSE Branch. will do summer internship in Rubrik Software Intern profile at Rubrik. Here are some brief insights."
      },
      {
        "type": "h2",
        "content": "Shortlisted Profiles & Companies:"
      },
      {
        "type": "p",
        "content": "Quadeye (Systems) Alphagrep (Systems) DE Shaw JPMC Rubrik Optiver (Systems) Google"
      },
      {
        "type": "h2",
        "content": "Insights on the Selection Process"
      },
      {
        "type": "p",
        "content": "Shortlisting on the basis of test. Then Interview, 2 Technical rounds, 1 HR round."
      },
      {
        "type": "h2",
        "content": "Preparation Resources"
      },
      {
        "type": "p",
        "content": "Codeforces Leetcode InterviewBit PuzzledQuant Brainstellar 50 Challenging problems in probability"
      },
      {
        "type": "h2",
        "content": "Advice for students (dos and don’ts)?"
      },
      {
        "type": "p",
        "content": "Do’s Start preparing early, because at the end of summer, tests will literally leave no time for skill building. Start at the beginning of summer if you want to learn any new skill/ improve coding. Focus on OOP concepts, they are asked a lot in quant firms (Optiver and alphagrep had a round specifically for OOP). Try to work on good self-projects which you can showcase in your resume as well. Don'ts Don’t start everything in the suggested resources at once, and it is fine if you don’t cover all the resources, first focus on understanding the higher level concepts and then practice more questions. If you attempt a coding problem, write actual code and not just the idea, translating your ideas into code is a very important skill in tests and interviews. Don’t just solve the complete question in the mind (applicable to both puzzles as well as coding problems), try to interactively solve them with friends, it improves your ability to express your ideas better."
      }
    ]
  },
