  "2024-intern-arnav-shendurnikar-american-express": {
    "slug": "2024-intern-arnav-shendurnikar-american-express",
    "wordCount": 296,
    "readTime": "2 min read",
    "blocks": [
      {
        "type": "p",
        "content": "Arnav Shendurnikar, studying in IIT Kanpur as a  student in Name Arnav Shendurnikar Roll No. 200929 Branch MTH Programme Double Major will do summer internship in American Express - Analytics profile at American Express. Here are some brief insights."
      },
      {
        "type": "h2",
        "content": "Shortlisted Profiles & Companies:"
      },
      {
        "type": "p",
        "content": "Microsoft – TPM Barclays – Quant"
      },
      {
        "type": "h2",
        "content": "Insights on the Selection Process"
      },
      {
        "type": "p",
        "content": "I had filled for analyst as well as software role. In software test they asked web development; The analyst test was pretty interesting. I consist of 24 questions, few were based on ML and few were word problems, like graphs were given and questions were asked on the basis of it. After that Resume Shortlisting were done."
      },
      {
        "type": "h2",
        "content": "Preparation Resources"
      },
      {
        "type": "p",
        "content": "Google Analytics Course on Coursera 50 Challenging Problems in Probability BrainStellar Striver 150 CS & CS (for Software) InterviewBit"
      },
      {
        "type": "h2",
        "content": "Advice for students (dos and don’ts)?"
      },
      {
        "type": "p",
        "content": "Start your preparation early. Don’t get dejected when you rare not able to solve questions specially coding problems. In the interview be active and try to converse with your interviewer, if there was something that I was not able to solve then I would ask the interviewer for hints. One thing more is that to have a short story around the points in your resume, because the interviewer will grill you on your resume. There should be a flow in your resume, like how did you get there, even in projects, why did you do that project. So, you should have some reason for that and things should feel natural. Start reading books, it will increase your reading speed & understand better and will help in solving analytics questions because they will give you 20 questions for about 30-45mins. Have a study partner with you to prepare so you do not lose your motivation."
      }
    ]
  },
