        "content": "Aryan Bansal, studying in IIT Kanpur as a  student in Name Aryan Bansal Roll No.  200198 Branch MTH-CSE Programme Double-Major (B.Tech) will do summer internship in Optiver- Trader Role profile at Optiver. Here are some brief insights."
