  "2024-intern-atharv-vibhas-jiwane-oracle": {
    "slug": "2024-intern-atharv-vibhas-jiwane-oracle",
    "wordCount": 592,
    "readTime": "3 min read",
    "blocks": [
      {
        "type": "p",
        "content": "Atharv vibhas jiwane, studying in IIT Kanpur as a  student in Name Atharv Jiwane Roll No.  210230 Branch Mechanical Engineering Programme B. Tech. will do summer internship in Oracle(Software resp.) profile at Oracle. Here are some brief insights."
      },
      {
        "type": "h2",
        "content": "Shortlisted Profiles & Companies:"
      },
      {
        "type": "ol",
        "content": [
          "ITC - KITES Summer Intern (Core) 2. Oracle - App. Dev./PDO Intern (Software)"
        ]
      },
      {
        "type": "h2",
        "content": "Insights on the Selection Process"
      },
      {
        "type": "p",
        "content": "ITC  Application form -> Test(?) -> Shortlist -> Group Discussion -> Shortlist -> 2 rounds of Interviews. • Lengthy form, I vaguely remember giving some sort of skill- assessment test which was gamified. • Group Discussion was based on the same question that was given by ITC last year. • 1st round of Interview was based on some questions related to projects and not-very-deep theoretical questions related to core mechanical course like thermodynamics, dynamics and fluids. • Interview panel consisted of a technical interviewer (IITK alum) and an HR interviewer. • Some family background and candidate background questions. • I would say that they were looking for someone with more project/work experience in the core field. • For core questions, revise basic concepts in thermodynamics like plots, engines, pumps, refrigerator, etc and dynamics and fluids like boundary layer, evaporation, etc. • Very few questions related to team management/ leadership questions related to the PORs that I had mentioned. • Did not make it to the second round of interviews. Oracle  Application Form -> Coding Test -> Shortlist -> 4 rounds of Interviews • Nominal form • The coding round was held offline in a lecture hall and was not proctored on the platform. There were 3 questions of increasing difficulty. The first two questions were of medium difficulty and the last one was hard. • Interview shortlist comes for two positions - Server Tech and Application Developer. • First Round - Introduction -> 1-2 generic medium-difficulty coding questions to solve on paper and explain -> I was lucky to be asked some questions about my department related to 3D printing and manufacturing based on the interviewers interest -> I was asked about my PORs • Second Round - Was asked to pick my preferred data structure and asked to generate a coding question and solve it on the spot. • Third Round - Generic questions related to high-school probability and statistics like histograms, medians and what is the chance that…?, etc. Mainly, a SQL task related to performing one of the joins was given (inner join as far as I remember). • Fourth Round - HR round. Were you born and brought up in India? Do you want to go for higher studies? Are you an Indian citizen?"
      },
      {
        "type": "h2",
        "content": "Preparation Resources"
      },
      {
        "type": "p",
        "content": "Listed above."
      },
      {
        "type": "h2",
        "content": "Advice for students (dos and don’ts)?"
      },
      {
        "type": "p",
        "content": "• Revise your projects well, learn to describe your project experience using the S.T.A.R. (Story/Background. Task/Goal. Approach. Result/Outcome) approach. A good background story always helps! • Review the tech stack that the company prefers. Ask seniors if the company asks questions about specific things for eg. Oracle questioned candidates about SQL apart from DSA. • Review requirements listed by the company, ask seniors for the type of questions that the company asks etc. • Don’t underestimate the importance of InterviewBit in your preparation. • Prepare your resume thoroughly. You should be able to describe and defend every line of your resume. • Don’t skip to the solution if you are stuck on a problem on LeetCode/ InterviewBit. Instead, persist for a while and try to figure the logic on your own. This has a propelling impact on your preparation."
      }
    ]
  },
  "2024-intern-avi-gupta-dr-reddys-laboratories--core-engineering": {
    "slug": "2024-intern-avi-gupta-dr-reddys-laboratories--core-engineering",
    "wordCount": 443,
    "readTime": "3 min read",
    "blocks": [
      {
        "type": "p",
        "content": "Avi Gupta, studying in IIT Kanpur as a  student in Name Avi Gupta Roll No.  210235 Branch Chemical Engineering Programme B.Tech will do summer internship in Dr. Reddy’s Laboratories – Core Engineering profile at Dr. Reddy’s Laboratories – Core Engineering. Here are some brief insights."
      },
      {
        "type": "h2",
        "content": "Shortlisted Profiles & Companies:"
      },
      {
        "type": "p",
        "content": "nan"
      },
      {
        "type": "h2",
        "content": "Insights on the Selection Process"
      },
      {
        "type": "p",
        "content": "There were 3 rounds in total 1. Test Test was online and had 3 sections · Technical Questions Related mostly to Thermodynamics, Fluid Mechanics and Heat Transfer in general · Aptitude Questions Typical aptitude problems like identifying the pattern, sequences and puzzles were asked. · HR Questions This question had HR questions like why DRL, why core type questions. 2. Group Discussion A topic related to chemical engineering and a few questions related to it were given. First everyone was asked to speak for 2 minutes turn by turn on a given question of their choosing and later everyone was asked to join in like a typical GD. 3. Interview There were 2 rounds · Technical Round Mostly they ask questions related to some core stuff about reactors, heat transfer or mass transfer. Sometimes they ask you your favourite course and questions from it. · HR Round This was a long round, the interviewer would ask you to go through your resume once and typical HR questions like why DRL, why Core etc. were asked here as well."
      },
      {
        "type": "h2",
        "content": "Preparation Resources"
      },
      {
        "type": "p",
        "content": "Core Stuff Going through notes of the courses taught in 2 nd year will be suffice. Just make sure that your concepts are clear in these courses. Mental Ability Solving previous year CAT questions can help. In my case going through puzzles section of Interviewbit and solving Brainstellar helped a lot. GD Joining sessions organized by AnC and SPO for GD practice would help a lot. You can also practice GDs with your friends in general, just make sure you have a senior who joins to guide and explain you how to proceed in a GD."
      },
      {
        "type": "h2",
        "content": "Advice for students (dos and don’ts)?"
      },
      {
        "type": "p",
        "content": "Dos · Try to narrow down the profiles you are targeting as early as possible, narrowing down preparation to 2-3 profiles is better. · Having a diverse profile helps a lot in case of core jobs. · Try to have atleast one project related to domain you are targeting. Don’ts · Try not to rely completely on profiles like Techno-managerial and Consulting as shortlisting in these profiles are highly uncertain. Always have a backup in case you are targeting these profiles. · Don’t write anything on your resume that you are unsure of, make sure that you are thorough with your resume."
      }
    ]
  },
