  "2024-intern-geetika-uber": {
    "slug": "2024-intern-geetika-uber",
    "wordCount": 248,
    "readTime": "2 min read",
    "blocks": [
      {
        "type": "p",
        "content": "Geetika, studying in IIT Kanpur as a  student in nan will do summer internship in Uber(Software) profile at uber. Here are some brief insights."
      },
      {
        "type": "h2",
        "content": "Shortlisted Profiles & Companies:"
      },
      {
        "type": "p",
        "content": "1) Millenium (Quant) 2) Goldman Sachs 3) Quadeye (Systems and quant) 4) Microsoft (Software) 5) Sprinkler (Software) 6) Google (Software) 7) Tower (Limestone) 8) Uber (Software) 9) Morgan Stanley 10) Alphagrep (Systems) 11) NK Securities (Systems) 12) Trexquant"
      },
      {
        "type": "h2",
        "content": "Insights on the Selection Process"
      },
      {
        "type": "p",
        "content": "The first step in the selection process was an online assessment. It comprised of 3 questions based on DSA. At least 2-2.5 questions were required to be solved for getting shortlisted. Also, a shortlist in the Uber She++ test helps a lot. This was followed by release of shortlist and interview."
      },
      {
        "type": "h2",
        "content": "Preparation Resources"
      },
      {
        "type": "p",
        "content": "https//docs.google.com/document/d/1B7RspmjiI7ole224HBQ0XI1CoLGw1RDkTW5y0No9ilA/e dit?usp=sharing"
      },
      {
        "type": "h2",
        "content": "Advice for students (dos and don’ts)?"
      },
      {
        "type": "p",
        "content": "Choose your priority order beforehand. I missed some important interviews. I thought I would get shortlisted in quadeye because my interview went very well and my CPI was good, but clearly that was not the case, that’s why I went to Uber’s interview (I had choices like Millenium and trexquant). Take actions considering the worst possible scenarios in mind. Also prepare for one level higher than what you are targeting, at least in my case my performance decreased significantly because of stress. I practiced a lot of hard questions that helped me survive Intern season day1. Get a good sleep. I remember I was unable the sleep the night before day1 )"
      }
    ]
  },
