        "content": "Initially, there was a resume shortlisting, followed by a combined coding and aptitude test, and finally, one interview round. The test was relatively manageable, with coding questions of medium difficulty—around three, if memory serves correctly. I managed to solve two of them. Before the coding section, there was a timed aptitude segment, where we had to tackle as many questions as possible. The format involved an interesting twist Correct answers increased the difficulty of subsequent questions, while incorrect answers decreased it."
