        "content": "I focused most of my preparation efforts during the summer. However, I had also completed a DSA course during the 4th semester and regularly practiced competitive programming, which helped improve my coding skills. I primarily used InterviewBit for resources and continued practicing competitive programming in May. Additionally, during this time, I worked on an ML project under Professor Avinash Sir from May to July and completed a one-month internship from mid-June to mid-July."
