  "2024-intern-ravi-patel-sprinklr": {
    "slug": "2024-intern-ravi-patel-sprinklr",
    "wordCount": 274,
    "readTime": "2 min read",
    "blocks": [
      {
        "type": "p",
        "content": "Ravi Patel, studying in IIT Kanpur as a  student in Ravi Patel Roll No.  200777 Branch EE Programme Double Major will do summer internship in Sprinklr(Product Engineering Intern) profile at Sprinklr. Here are some brief insights."
      },
      {
        "type": "h2",
        "content": "Shortlisted Profiles & Companies:"
      },
      {
        "type": "ol",
        "content": [
          "Morgan Stanley (Sales & Trading) 2. Bain & Company 3. Boston Consulting Group 4. Goldman Sachs (Quantitative Strategists) 5. Google (SDE) 6. Sprinklr (Product Engineer)"
        ]
      },
      {
        "type": "h2",
        "content": "Insights on the Selection Process"
      },
      {
        "type": "p",
        "content": "Resume Shortlisting Technical Test (3 Coding Ques in 90 mins) Technical Interview (2 rounds) HR Interview"
      },
      {
        "type": "h2",
        "content": "Preparation Resources"
      },
      {
        "type": "p",
        "content": "Preparation strategy I started my preparation for internship drive during summer. I also made a rough draft of my resume to see where I needed to improve. For coding part, participated in almost every contest on Codechef & Codeforces during summers. Followed software roadmap & InterviewBit to practice coding questions. Also solved Puzzles & Probability ques from below mentioned resources. Resources 1. Competitive Coding (Codeforces & Codechef) 2. DSA (Geeks for Geeks – for theory; Leetcode & InterviewBit – for practice) 3. Software Roadmap https//spo.iitk.ac.in/assets/Roadmap_SDE.pdf 4. Prob & Stats 50 Challenging Problems in Probability 5. Puzzles https//brainstellar.com/puzzles https//www.puzzledquant.com/ (for those who are also preparing for Quant roles)"
      },
      {
        "type": "h2",
        "content": "Advice for students (dos and don’ts)?"
      },
      {
        "type": "p",
        "content": "For DSA prep, solve each & every question of InterviewBit (atleast 2 times both Programming & Puzzles section). Sometimes questions are directly asked (or with small variation) from here. Don’t wait till the last minute to make your resume. Prepare thoroughly (with proper reasoning) what you have written in it. You can expect questions like why this project, why low CPI, why this POR etc. All the Best!"
      }
    ]
  },
  "2024-intern-rishi-jaiswal-samsung-rd-banglore": {
    "slug": "2024-intern-rishi-jaiswal-samsung-rd-banglore",
    "wordCount": 354,
    "readTime": "2 min read",
    "blocks": [
      {
        "type": "p",
        "content": "Rishi Jaiswal, studying in IIT Kanpur as a  student in Name Rishi Jaiswal Roll No.  210850 Branch Electrical Engineering Programme B-tech 4 year will do summer internship in Companies Samsung R&D Bangalore profile at Samsung R&D Banglore. Here are some brief insights."
      },
      {
        "type": "h2",
        "content": "Shortlisted Profiles & Companies:"
      },
      {
        "type": "p",
        "content": "Goldman Sachs (Quant) analyst) Adobe (SDE) Qualcomm (SDE) Samsung R&D Bangalore (SDE)"
      },
      {
        "type": "h2",
        "content": "Insights on the Selection Process"
      },
      {
        "type": "p",
        "content": "This internship is mainly for electrical engineering (EE) students, with the shortlist based on resume reviews and a coding assessment. After that, there was just one interview round, which included both technical and HR questions."
      },
      {
        "type": "h2",
        "content": "Preparation Resources"
      },
      {
        "type": "p",
        "content": "nan"
      },
      {
        "type": "h2",
        "content": "Advice for students (dos and don’ts)?"
      },
      {
        "type": "p",
        "content": "Samsung R&D is the company that selected me, but you might be interested in hearing why I wasn't selected by other companies that interviewed me before this. My first interview was with Goldman Sachs. It was my first interview ever, so I was extremely nervous, and my preparation wasn't great—I struggled with coding and, more importantly, with probability and statistics. I want to emphasize that MSO201, which covers probability and statistics, is a crucial part of your preparation. The interviewer spent almost 30 minutes asking me about MSO concepts. So, if you're aiming for companies like Goldman Sachs, you must be confident in your coding skills, which only comes with thorough preparation, and you should have a solid understanding of MSO topics. This knowledge is also helpful for roles like quant analyst. The next interview was with Adobe, which was purely coding-based. Since I wasn't well- prepared for coding, I struggled and was rejected. The third interview was for a Qualcomm SDE role. During the interview, they mainly asked me about concepts from ESC201, EE200, and EE250. This was the best interview I ever had, but in the end, they only selected candidates from the CSE for the SDE role, as far as I recall. In conclusion, if you're confident in your skills, your interviews will likely go well. However, if you're underprepared, you'll find it challenging. My advice is to prepare thoroughly and stay calm during interviews. Good luck and prepare well!"
      }
    ]
  },
