        "content": "For Microsoft and Sprinklr, there was 1 coding test, students were shortlisted for interview based on resume and the coding round. Optiver had an initial round with games and some MCQ questions based on CS fundamentals, the next coding test had 3 questions, 2 easy implementations based, 1 hard. Shortlisting was mostly based on performance, resume played little role. Microsoft had 2 interview rounds, one coding question was asked in each round. Sprinklr also had 2 coding rounds, some puzzles were also asked in 2nd round. Optiver had 3 interview rounds, 1 based on system design, 1 on algorithmic coding, and 1 HR round."
