        "content": "The first step in the recruitment process was a nationwide CodeThon. It comprised of good level of DSA questions. I was included in the extended shortlist from the codethon. Then, there was an online assessment for the extended shortlist candidates comprising of 3 coding questions, and I solved 2 of them and was selected for the interview."
