        "content": "Projects are very important as it makes you stand apart from others. I did projects in ML, Web Dev and Robotics. I also did internship in SURGE. Self projects are also good peaks for resume. Practicing techno-managerial questions before hand by giving mock interviews is a must to give the HR round confidently. As in Cisco’s process many candidates cleared the first 2 rounds but were rejected in HR round. Giving mock interview on interview-bit and other websites or even to your seniors who have cleared the interviews will be helpful. CS fundamentals are also important and can be asked in interviews, so remember to cover them too."
