        "content": "\"Test – 60 MCQ (aptitude, puzzles, math, logical reasoning and 1-2 questions on MasterCard history) 1 descriptive question (A world map was given with some points marked on it and lines were drawn connecting these points, we were asked to describe what we deduced from this) – for this I replied that this were all the MasterCard offices located throughout the world and in the interview, they asked about how I got to this answer and what was the thought process.\""
