  "2024-intern-snehal-shridhar-kane-american-express": {
    "slug": "2024-intern-snehal-shridhar-kane-american-express",
    "wordCount": 367,
    "readTime": "2 min read",
    "blocks": [
      {
        "type": "p",
        "content": "Snehal Shridhar Kane, studying in IIT Kanpur as a  student in Snehal S. Kane Roll No.  211044 Branch MSE Programme B Tech Any other things you will like to tell us about yourself (Optional) I was a CTM in my third year will do summer internship in American Express – Product Profile Analyst Profile profile at American Express. Here are some brief insights."
      },
      {
        "type": "h2",
        "content": "Shortlisted Profiles & Companies:"
      },
      {
        "type": "p",
        "content": "American Express-Analytics"
      },
      {
        "type": "h2",
        "content": "Insights on the Selection Process"
      },
      {
        "type": "p",
        "content": "Technical Test - CPI criteria  CPI > 7 OPEN to all branches Consisted of 3 sections - General Aptitude Case study ML questions - Basic MCQ types Resume shortlisting - CPI >= 7.5 Interview - Two eliminatory rounds will be conducted. Upon clearing the first round you go to the next one. Round 1 - Walking through your resume; Explaining projects; Solving puzzles; HR type questions Round 2 - Solving Guesstimates and more technical questions"
      },
      {
        "type": "h2",
        "content": "Preparation Resources"
      },
      {
        "type": "p",
        "content": "nan"
      },
      {
        "type": "h2",
        "content": "Advice for students (dos and don’ts)?"
      },
      {
        "type": "p",
        "content": "Talk to seniors who have been selected in your company of interest. They can give you first hand experiences of their interviews and kind of questions asked Listen to the company’s PPT intently. It might help you in the HR questions asked in your interviews Once interview fixed, try to collect maximum info about the company’s business model, products, financial numbers etc Be familiar with general HR questions Articulate your thoughts well and think out aloud while solving puzzles and guesstimates. Know current basic numerals of Indian economy to answer guesstimates. Some more important points  Make a good resume with as much relevant projects as possible. Unlike consulting resumes, extracurriculars and PORs need not be very elaborate. Get your resume verified by as much seniors as possible. You might get mixed opinions, finally stick to what you find the best. You can target a specific company while making a specific domain resume. For analytics including projects which involve ML concepts is a big plus. Knowing SQL is a sweet spot. It is alright if you know just the basics. It is really easy and watching any Youtube video will give you a fair working idea. Have fair understanding of ML concepts to answer technical questions."
      }
    ]
  },
