  "2024-intern-tarun-goyal-barclays": {
    "slug": "2024-intern-tarun-goyal-barclays",
    "wordCount": 307,
    "readTime": "2 min read",
    "blocks": [
      {
        "type": "p",
        "content": "Tarun Goyal, studying in IIT Kanpur as a  student in Tarun Goyal,211102,MTH will do summer internship in Barclays(Quantitative Developer Intern) profile at Barclays. Here are some brief insights."
      },
      {
        "type": "h2",
        "content": "Shortlisted Profiles & Companies:"
      },
      {
        "type": "p",
        "content": "McKinsey Millenium"
      },
      {
        "type": "h2",
        "content": "Insights on the Selection Process"
      },
      {
        "type": "p",
        "content": "The selection process is pretty simple if you look at it. The main tasks are getting shortlisted for the interview and then cracking it. Those two were the main problems where I faced many questions as to what will happen and what won't. I was not shortlisted at the start for many companies. I was shortlisted for McKinsey and waitlisted for Millenium. I gave my interview at millenium and was able to crack all the rounds. The HR round however didn't go that well and they had to go with the other candidate. After that I gave interviews at databricks, finmechanics and Barclays. I got my free at Barclays after a long 6 hours of interview process."
      },
      {
        "type": "h2",
        "content": "Preparation Resources"
      },
      {
        "type": "p",
        "content": "Leetcode InterviewBit 50 challenges in probability Brainstellar"
      },
      {
        "type": "h2",
        "content": "Advice for students (dos and don’ts)?"
      },
      {
        "type": "p",
        "content": "There is a way to actually do all of it altogether and do well enough. The first step is definitely making sure you know the syllabus, the next step being practice practice. The way to practice is by doing questions side by side learning topics. Interviewbit offers a very good way of doing this because of its interface. Side by side it's good to check out the medium and hard problems in leetcode as they are good to have done. To make your preparation stand out, you can actually document the questions you do on notion, of leetcode. There are plenty of resources available for this. coming to the puzzles and all, you can either solve it all at once or a few everyday but you need to be consistent about it"
      }
    ]
  },
