        "content": "Test has aptitude and coding MCQ questions. It was a pen paper test with different sets and moderate questions for the technical aspect and easy to moderate for the aptitude aspect. Round 1 of Interviews were taken by junior members of the recruiting team and the questions were brainstellar type and they asked a couple of coding questions and my preference for tech or consulting. Round 2 was a complete stress test and character test. It was taken by CXO level recruiters. I was asked questions on my resume and abstract questions to test critical thinking."
