  "2024-placement-nibir-baruah-quantbox-research": {
    "slug": "2024-placement-nibir-baruah-quantbox-research",
    "wordCount": 311,
    "readTime": "2 min read",
    "blocks": [
      {
        "type": "p",
        "content": "Hi, my name is Nibir Baruah, 19807545. I am a BT-MT student in the department of Computer Science and Engineering. My interests mainly lie in parallel programming, computer architecture and operating systems. For my thesis project, I have been working on analysing and improving the performance of common filesystems like f2fs and ext4 on multi-device persistency configurations, mainly focusing on SSDs and HDDs., studying in IIT Kanpur will be joining Quantbox Research - Core Engineering Analyst. Here are some brief insights."
      },
      {
        "type": "h2",
        "content": "Shortlisted Profiles & Companies:"
      },
      {
        "type": "p",
        "content": "1.Graviton (Software) 2.NK Securities (Software) 3.Google (SDE) 4.Squarepoint (Software)"
      },
      {
        "type": "h2",
        "content": "Selection Process of the Company you are selected in 1) Resume Shortlist, 2) GD, 3)Test"
      },
      {
        "type": "ol",
        "content": [
          "Resume Shortlist 2.Online Test 3. Interview"
        ]
      },
      {
        "type": "h2",
        "content": "Insights on the interview process"
      },
      {
        "type": "p",
        "content": "The interview process had 2 rounds. Round 1) This had both theoretical and programming components. For the theory part, I was asked advanced OOPS concepts, modern c++, parallel programming, concurrent data structures, cache concepts. Programming involved coding up some modern c++ data structure, using threads with and without locks to implement a solution for a problem. I was also asked to implement some functions using c++ templates. Round 2) This round was mainly theoretical. We had a very good discussion on hashing and different ways on improving it. Then there were some theoretical and programming questions on how memory can be used efficiently."
      },
      {
        "type": "h2",
        "content": "Sample Interview Questions?"
      },
      {
        "type": "p",
        "content": "N.A."
      },
      {
        "type": "h2",
        "content": "Preparation Resources"
      },
      {
        "type": "p",
        "content": "1.Codeforces 2.leetcode 3.C++ books like Effective Modern c++ by Scott Meyers 4. learncpp.com, 5.cppnow and cppcon videos on youtube."
      },
      {
        "type": "h2",
        "content": "Advice for students (do's and don'ts)"
      },
      {
        "type": "p",
        "content": "Practice coding regularly on codeforces and leetcode. Keep your CGPA decent. I would recommend keeping it above 9. If you are preparing for systems role, you have to study separately for that. The core CS courses help a lot in this. Try to also do some projects in that area."
      }
    ]
  },
