        "content": "Interviews were focused on the basics of your discipline (Mechanical Engineering in my case) and your projects/internship work. I was asked about the basics of thermodynamics and theory of machines. I had worked as an operations intern at Dr. Reddy’s Laboratories, so I was questioned on the same and also on manufacturing in general. I had worked at Siemens on the digital twin technology and was grilled on that."
